"""agents.py: stand-in shop agents for Lab 4 (you do not edit this file).

A real agent is a model with a prompt and tools. So that the lab runs offline and gives the same
results every time, ShopAgent plays one. It does the right thing (look the order up, check the
policy, act or decline, report) except when a seeded random draw says this step goes wrong. The
ways it goes wrong are the ones chapter 8 lists:

    wrong_item   refunds a different item than the customer asked for, and reports the right one
    claim_only   skips the write and reports success
    garble       changes the address but drops the house number
    wrong_order  reads or changes a different order
    override     ignores the policy and does it anyway (a refund past the return window, say)
    loop         keeps re-reading the order until the harness stops it

act(env, task, rng) reads the task's steps (a real agent would read the customer's messages). It
draws THREE numbers per step from rng, always, whatever happens next, so that two agents given the
same rng see the same luck: that is what makes a paired comparison fair.

AGENT_V1 is the baseline. AGENT_V2 adds a verification read before every write and catches 60%
of of the mistakes V1 would have made, at the price of one more tool call per write.
"""
from shop import PRICES, RETURN_WINDOW_DAYS

WEIGHTS = {  # given that a step goes wrong, which way? (cumulative order matters)
    "refund": [("wrong_item", 0.4), ("claim_only", 0.4), ("loop", 0.2)],
    "address": [("garble", 0.4), ("claim_only", 0.4), ("wrong_order", 0.2)],
    "status": [("wrong_order", 1.0)],
}


class ShopAgent:
    def __init__(self, name, error_rate, verify=False, catch=0.75):
        self.name = name
        self.error_rate = error_rate      # chance a step goes wrong, by kind: refund / address / status / decline
        self.verify = verify
        self.catch = catch

    def __repr__(self):
        return f"ShopAgent({self.name})"

    # ------------------------------------------------------------------ one trial
    def act(self, env, task, rng):
        parts = [self._step(env, step, task.get("hardness", 1.0), rng.random(), rng.random(), rng.random())
                 for step in task["steps"]]
        return env.say(" ".join(parts))

    # ------------------------------------------------------------------ one step
    def _step(self, env, step, hardness, u, m, c):
        kind, order = step["kind"], step["order"]
        info = env.call("lookup_order", order=order)
        if isinstance(info, str):
            return f"I cannot find order {order}."
        reason = self._policy(kind, step, info)
        p = min(1.0, hardness * self.error_rate["decline" if reason else kind])
        wrong = u < p
        if self.verify and kind != "status":
            env.call("lookup_order", order=order)               # the extra, costly read before acting
            if wrong and c < self.catch:
                wrong = False
        if reason:
            if wrong:                                           # override: do it anyway
                self._write(env, step)
                return "Done."
            return f"Sorry, I cannot do that: {reason}."
        mode = self._mode(kind, m) if wrong else None
        return self._do(env, step, info, mode)

    @staticmethod
    def _policy(kind, step, info):
        """Why the shop's policy says no, or None if the request is fine."""
        order = step["order"]
        if kind == "refund":
            if info["status"] != "delivered":
                return f"order {order} has not been delivered yet"
            if step["item"] not in info["items"]:
                return f"the {step['item']} is not in order {order}"
            if info["days_since_delivery"] > RETURN_WINDOW_DAYS:
                return f"it was delivered {info['days_since_delivery']} days ago and returns close after {RETURN_WINDOW_DAYS} days"
        if kind == "address" and info["status"] != "processing":
            return f"order {order} has already shipped"
        return None

    @staticmethod
    def _mode(kind, m):
        acc = 0.0
        for mode, w in WEIGHTS[kind]:
            acc += w
            if m < acc:
                return mode
        return WEIGHTS[kind][-1][0]

    @staticmethod
    def _write(env, step):
        if step["kind"] == "refund":
            return env.call("refund_item", order=step["order"], item=step["item"])
        return env.call("change_address", order=step["order"], address=step["address"])

    def _do(self, env, step, info, mode):
        kind, order = step["kind"], step["order"]
        if mode == "loop":
            while True:
                env.call("lookup_order", order=order)           # ends with StepCapExceeded
        if kind == "status":
            if mode == "wrong_order":
                other = next(o for o in sorted(env.db["orders"]) if env.db["orders"][o]["status"] != info["status"])
                return f"Order {other} is {env.db['orders'][other]['status']}."
            return f"Order {order} is {info['status']}."
        if kind == "refund":
            item = step["item"]
            if mode == "wrong_item" and len(info["items"]) > 1:
                env.call("refund_item", order=order, item=next(i for i in info["items"] if i != item))
            elif mode != "claim_only" and mode != "wrong_item":
                env.call("refund_item", order=order, item=item)
            return f"Done: the {item} from {order} is refunded, {PRICES[item]} dollars."
        address = step["address"]                               # kind == "address"
        if mode == "wrong_order":
            other = next(o for o in sorted(env.db["orders"]) if o != order and env.db["orders"][o]["status"] == "processing")
            env.call("change_address", order=other, address=address)
        elif mode == "garble":
            env.call("change_address", order=order, address=address.split(" ", 1)[1])
        elif mode != "claim_only":
            env.call("change_address", order=order, address=address)
        return f"Done: the address of {order} is now {address}."


V1_RATES = {"refund": 0.15, "address": 0.18, "status": 0.05, "decline": 0.30}
AGENT_V1 = ShopAgent("v1", V1_RATES)
AGENT_V2 = ShopAgent("v2", V1_RATES, verify=True, catch=0.6)
REFERENCE = ShopAgent("reference", {"refund": 0.0, "address": 0.0, "status": 0.0, "decline": 0.0})
